import { state, IContext } from 'cerebral'
import { AppService } from '../src/AppService'
import { runCompute, CerebralTest } from 'cerebral/test'
import { CerebralComponent } from '../src/CerebralComponent'
import { connect } from '../src/connect'
import { createMockCdr } from './helpers'

describe('Angular Cerebral Integration', () => {
  it('should export the required items', () => {
    expect(AppService).toBeDefined()
    expect(CerebralComponent).toBeDefined()
    expect(connect).toBeDefined()
  })

  describe('CerebralComponent', () => {
    it('should require CDR and controller', () => {
      expect(() => new CerebralComponent(null, null)).toThrow(
        /ChangeDetectorRef/
      )

      const validCdr = createMockCdr()
      expect(() => new CerebralComponent(validCdr, null)).toThrow(/AppService/)
    })

    it('should initialize with proper arguments', () => {
      const mockCDR = createMockCdr()
      const mockCtrl = { flush: jest.fn() }
      const component = new CerebralComponent(mockCDR, mockCtrl)

      expect(component._cdr).toBe(mockCDR)
      expect(component._app).toBe(mockCtrl)
    })
  })

  describe('AppService', () => {
    it('should create a Cerebral controller', () => {
      const increase = ({ store, get }: IContext<object>) => {
        const currentCount = get(state`count`)
        store.set('count', currentCount ? currentCount + 1 : 1)
      }

      const store = {
        state: { count: 42 },
        sequences: { increase: [increase] },
      }

      const controller = new AppService(store)

      expect(typeof controller.getState).toBe('function')
      expect(controller.getState('count')).toBe(42)

      const model = controller.getModel()
      model.set(['count'], 43)
      expect(controller.getState('count')).toBe(43)

      const inc = controller.getSequence('increase')
      inc()
      expect(controller.getState('count')).toBe(44)
    })
  })

  describe('connect', () => {
    it('should be a function returning a decorator function', () => {
      expect(typeof connect).toBe('function')
      expect(typeof connect({})).toBe('function')
    })
  })
})

describe('Cerebral Advanced Features', () => {
  describe('Computed Values', () => {
    it('should work with computed values as described in README', () => {
      type Items = Array<{ id: number; name: string }>

      type State = {
        items: Array<{ id: number; name: string }>
        filter: string
        filteredItems?: Items
      }

      // Fix the compute function to use the get parameter properly
      const filteredItems = (get: any) => {
        const items: Items = get(state`items`) // Use get to retrieve the state value
        const filter: string = get(state`filter`) // Use get to retrieve the state value

        return items.filter((item) =>
          filter ? item.name.includes(filter) : true
        )
      }

      // Test with initial state - no filter
      const initialResult = runCompute(filteredItems, {
        state: {
          items: [
            { id: 1, name: 'Item 1' },
            { id: 2, name: 'Item 2' },
            { id: 3, name: 'Test 3' },
          ],
          filter: '',
        } as State,
      })

      expect(initialResult.length).toBe(3)

      // Test with "Item" filter
      const itemFilterResult = runCompute(filteredItems, {
        state: {
          items: [
            { id: 1, name: 'Item 1' },
            { id: 2, name: 'Item 2' },
            { id: 3, name: 'Test 3' },
          ],
          filter: 'Item',
        },
      })

      expect(itemFilterResult.length).toBe(2)

      // Test with "Test" filter
      const testFilterResult = runCompute(filteredItems, {
        state: {
          items: [
            { id: 1, name: 'Item 1' },
            { id: 2, name: 'Item 2' },
            { id: 3, name: 'Test 3' },
          ],
          filter: 'Test',
        },
      })

      expect(testFilterResult.length).toBe(1)
    })
  })

  describe('Angular Services in Cerebral', () => {
    it('should work with service providers as described in README', async () => {
      // Define mock HTTP service matching the README example
      const mockHttp = {
        get: jest.fn().mockResolvedValue({ data: 'test data' }),
      }

      // Setup controller as shown in README
      const test = CerebralTest({
        state: {
          loading: false,
          data: null,
          error: null,
        },
        sequences: {
          fetchData: [
            ({ store }: any) => store.set('loading', true),
            async ({ http }: any) => {
              try {
                const response = await http.get('/api/data')
                return { response }
              } catch (error) {
                return { error }
              }
            },
            ({ store, props }: any) => {
              if (props.error) {
                store.set('error', props.error)
              } else {
                store.set('data', props.response)
              }
              store.set('loading', false)
            },
          ],
        },
        providers: {
          http: mockHttp,
        },
      })

      // Run sequence
      await test.runSequence('fetchData')

      // Verify provider was called
      expect(mockHttp.get).toHaveBeenCalledWith('/api/data')

      // Check final state
      expect(test.getState('loading')).toBe(false)
      expect(test.getState('data')).toEqual({ data: 'test data' })
      expect(test.getState('error')).toBe(null)
    })

    it('should handle errors from providers as described in README', async () => {
      // Error-throwing provider
      const errorHttp = {
        get: jest.fn().mockRejectedValue(new Error('Network error')),
      }

      // Setup test app
      const test = CerebralTest({
        state: {
          loading: false,
          data: null,
          error: null,
        },
        sequences: {
          fetchData: [
            ({ store }: any) => store.set('loading', true),
            async ({ http }: any) => {
              try {
                const response = await http.get('/api/data')
                return { response }
              } catch (error) {
                return { error }
              }
            },
            ({ store, props }: any) => {
              if (props.error) {
                store.set('error', props.error)
              } else {
                store.set('data', props.response)
              }
              store.set('loading', false)
            },
          ],
        },
        providers: {
          http: errorHttp,
        },
      })

      // Run sequence
      await test.runSequence('fetchData')

      // Verify provider was called
      expect(errorHttp.get).toHaveBeenCalledWith('/api/data')

      // Check final state
      expect(test.getState('loading')).toBe(false)
      expect(test.getState('data')).toBe(null)
      expect(test.getState('error')).toBeInstanceOf(Error)
      expect(test.getState('error').message).toBe('Network error')
    })
  })
})
